const ALPHABET = 'abcdefghijkmnpqrstuvwxyz23456789'

function code(seed) {
  let out = ''
  for (let i = 0; i < 6; i += 1) out += ALPHABET[(seed + i * 31) % ALPHABET.length]
  return out
}

export function handler(req, ctx) {
  const body = req.json() ?? {}

  if (body.url) {
    // Seeded from the length and first character rather than at random:
    // the same URL in a session should come back as the same code.
    const key = code(body.url.length + body.url.charCodeAt(0))
    ctx.set(`link:${key}`, body.url)
    return { statusCode: 201, body: { code: key } }
  }

  if (body.code) {
    const target = ctx.get(`link:${body.code}`, null)
    if (!target) return { statusCode: 404, body: { error: 'unknown code' } }
    return { statusCode: 302, headers: { location: target }, body: null }
  }

  return { statusCode: 400, body: { error: 'send either url or code' } }
}
